-- =============================================================================================
-- Hand-written below this line: endpoints use HTTPS to a public-looking host, at most 20 event
-- types; the secret version only rises. Deliveries go only to active endpoints subscribed to the
-- event, never change, and are handed to the worker through the outbox in the same transaction;
-- outcomes are written only by app_webhook_delivery_result() (the application role has no UPDATE
-- on deliveries). The worker checks the resolved address again before sending. See
-- docs/architecture/DATA_MODEL.md section 11 (Webhooks).
-- =============================================================================================

ALTER TABLE "webhook_endpoints" ADD CONSTRAINT "webhook_endpoints_shape"
  CHECK (length("url") BETWEEN 12 AND 500
         AND "url" ~ '^https://[A-Za-z0-9.-]+(:[0-9]{2,5})?(/[^[:space:]]*)?$'
         AND lower(substring("url" FROM '^https://([^/:]+)')) !~ '^(localhost|.*\.local|.*\.internal|[0-9.]+|\[.*\])$'
         AND ("description" IS NULL OR ("description" = btrim("description") AND length("description") BETWEEN 1 AND 200))
         AND cardinality("events") BETWEEN 1 AND 20
         AND "secret_version" >= 1);

CREATE FUNCTION app_webhook_endpoint_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW."secret_version" := 1;
    NEW."created_at" := now();
    RETURN NEW;
  END IF;
  IF (NEW."organisation_id", NEW."created_by_user_id", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'an endpoint keeps its organisation and creator' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."secret_version" < OLD."secret_version" OR NEW."secret_version" > OLD."secret_version" + 1 THEN
    RAISE EXCEPTION 'secrets only rotate forward, one at a time' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "webhook_endpoints_guard"
  BEFORE INSERT OR UPDATE ON "webhook_endpoints"
  FOR EACH ROW EXECUTE FUNCTION app_webhook_endpoint_guard();

ALTER TABLE "webhook_deliveries" ADD CONSTRAINT "webhook_deliveries_shape"
  CHECK ("event_type" ~ '^[a-z_]+(\.[a-z_]+)+$' AND length("event_type") <= 80
         AND "attempts" >= 0
         AND ("status" = 'SUCCEEDED') = ("delivered_at" IS NOT NULL)
         AND ("last_error" IS NULL OR length("last_error") <= 500)
         AND pg_column_size("payload") <= 16384);

CREATE FUNCTION app_webhook_delivery_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM "webhook_endpoints"
     WHERE "id" = NEW."endpoint_id" AND "status" = 'ACTIVE'
       AND (NEW."event_type" = 'webhook.test' OR NEW."event_type" = ANY ("events"))
  ) THEN
    RAISE EXCEPTION 'the endpoint is disabled or does not take this event' USING ERRCODE = 'check_violation';
  END IF;
  NEW."status" := 'PENDING';
  NEW."attempts" := 0;
  NEW."last_status_code" := NULL;
  NEW."last_error" := NULL;
  NEW."delivered_at" := NULL;
  NEW."created_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "webhook_deliveries_guard"
  BEFORE INSERT ON "webhook_deliveries"
  FOR EACH ROW EXECUTE FUNCTION app_webhook_delivery_guard();

CREATE FUNCTION app_webhook_delivery_enqueue() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  INSERT INTO "outbox_events" ("id", "organisation_id", "type", "payload", "available_at")
  VALUES (gen_random_uuid(), NEW."organisation_id", 'webhook.delivery.due',
          jsonb_build_object('deliveryId', NEW."id"), now());
  RETURN NULL;
END
$$;

CREATE TRIGGER "webhook_deliveries_enqueue"
  AFTER INSERT ON "webhook_deliveries"
  FOR EACH ROW EXECUTE FUNCTION app_webhook_delivery_enqueue();

-- The worker's record of one attempt, and the only way an outcome is written (runs as the schema
-- owner; row-level security still limits it to the caller's tenant). A delivery that is no longer
-- pending is left alone, so a duplicated job is harmless.
CREATE FUNCTION app_webhook_delivery_result(p_delivery uuid, p_succeeded boolean, p_status_code int,
                                            p_error text, p_max_attempts int)
  RETURNS "WebhookDeliveryStatus"
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
DECLARE
  d record;
  next_status "WebhookDeliveryStatus";
BEGIN
  SELECT * INTO d FROM "webhook_deliveries"
   WHERE "id" = p_delivery AND "organisation_id" = app_current_organisation_id() FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such delivery' USING ERRCODE = 'no_data_found';
  END IF;
  IF d."status" <> 'PENDING' THEN
    RETURN d."status";
  END IF;
  next_status := CASE WHEN p_succeeded THEN 'SUCCEEDED'
                      WHEN d."attempts" + 1 >= p_max_attempts THEN 'FAILED'
                      ELSE 'PENDING' END;
  UPDATE "webhook_deliveries"
     SET "status" = next_status,
         "attempts" = d."attempts" + 1,
         "last_status_code" = p_status_code,
         "last_error" = CASE WHEN p_succeeded THEN NULL ELSE left(p_error, 500) END,
         "delivered_at" = CASE WHEN p_succeeded THEN now() END
   WHERE "id" = p_delivery;
  RETURN next_status;
END
$$;

GRANT EXECUTE ON FUNCTION app_webhook_delivery_result(uuid, boolean, int, text, int) TO veyra_app;

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['webhook_endpoints', 'webhook_deliveries'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "webhook_endpoints", "webhook_deliveries" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "webhook_endpoints" TO veyra_app;
GRANT SELECT, INSERT ON "webhook_deliveries" TO veyra_app;
